Search behavior lives in **`searchProducts`** in `ProductSelectionBasket.tsx`. It only matches when `kind === "product"` and **`n.label`** contains the trimmed, lowercased query; the category path is built for display (`trail`) but **not** used for matching.

```169:198:packages/ui-certification/src/components/traject/ProductSelectionBasket.tsx
function searchProducts(
  query: string,
  roots: readonly TreeNode[],
  routeEntry: AvailableEntry | undefined,
): SearchHit[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  const out: SearchHit[] = [];
  const walk = (input: readonly TreeNode[], trail: readonly string[]) => {
    for (const n of input) {
      if (
        n.kind === "product" &&
        n.label.toLowerCase().includes(q) &&
        productEligibleForCatalogEntry(n, routeEntry)
      ) {
        out.push({ id: n.id, label: n.label, categoryTrail: trail.join(" > ") });
      }
      if (n.children?.length) {
        walk(n.children, [...trail, n.label]);
      }
    }
  };
  walk(roots, []);
  return out.sort((a, b) => {
    const byTrail = a.categoryTrail.localeCompare(b.categoryTrail, "nl", {
      sensitivity: "base",
    });
    return byTrail !== 0 ? byTrail : byLabel(a, b);
  });
}
